import { Clock, ArrowRight } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { latestUpdateGroups } from '../lib/selectors'
import { navigate } from '../lib/router'
import { relativeDate, cx, seriesHref, chapterHref, genreHref } from '../lib/utils'
import Cover from '../components/Cover'
import { StatusBadge } from '../components/ui'

const link =
  (to: string) =>
  (e: React.MouseEvent): void => {
    if (e.metaKey || e.ctrlKey) return
    e.preventDefault()
    navigate(to)
  }

const keepExploring = [
  { href: '/catalog', title: 'Browse Catalog', hint: 'Every series in one place' },
  { href: '/genres', title: 'Genre Directory', hint: 'Find your next obsession' },
  { href: '/rankings', title: 'Rankings', hint: 'The top of the charts' },
]

export default function Updates({ page }: { page?: number }) {
  const { series, loading } = useCatalog()
  // /updates shows the newest 60 rows; /updates/page/{n} (mirroring the
  // prerendered pagination) shows that 60-row window of the full feed
  const pageNum = page && page > 1 ? page : null
  const allGroups = latestUpdateGroups(series, pageNum ? 100000 : 60)
  let groups = allGroups
  if (pageNum) {
    const rows = allGroups.flatMap((g) => g.rows)
    const windowRows = rows.slice((pageNum - 1) * 60, pageNum * 60)
    const regrouped: typeof allGroups = []
    for (const row of windowRows) {
      const key = `d:${row.chapters[0]?.releaseDate ?? ''}`
      let g = regrouped.find((x) => x.key === key)
      if (!g) {
        g = { key, label: '', rows: [] }
        regrouped.push(g)
      }
      g.rows.push(row)
    }
    groups = regrouped
  }
  const totalRows = groups.reduce((n, g) => n + g.rows.length, 0)

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div
        className="border-b border-line"
        style={{
          background:
            'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)',
        }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <div className="eyebrow text-accent">Latest Updates</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            Latest Manhwa Updates
          </h1>
          <p className="mt-3 max-w-xl text-white/70">
            Every new chapter as it drops — see which series updated today, yesterday, and this
            week across the whole catalog.
          </p>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{loading ? '…' : totalRows}</strong> recently updated
              series
            </span>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        {loading ? (
          <div className="space-y-8">
            {Array.from({ length: 3 }).map((_, gi) => (
              <div key={gi}>
                <div className="mb-3 h-4 w-32 animate-pulse rounded bg-paper-3/60" />
                <div className="grid gap-3 lg:grid-cols-2">
                  {Array.from({ length: 4 }).map((_, i) => (
                    <div
                      key={i}
                      className="flex gap-4 rounded-[14px] border border-line bg-paper p-3.5"
                    >
                      <div className="h-[104px] w-[76px] shrink-0 animate-pulse rounded-lg bg-paper-3/60" />
                      <div className="min-w-0 flex-1 space-y-2">
                        <div className="h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
                        <div className="h-3 w-1/2 animate-pulse rounded bg-paper-3/60" />
                        <div className="h-3 w-full animate-pulse rounded bg-paper-3/60" />
                        <div className="h-3 w-2/3 animate-pulse rounded bg-paper-3/60" />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="space-y-7">
            {groups.map((group) => (
              <div key={group.key}>
                <div className="mb-3 flex items-center gap-3">
                  <h3
                    className={cx(
                      'text-sm font-extrabold uppercase tracking-wide',
                      group.label === 'Today' ? 'text-accent' : 'text-ink',
                    )}
                  >
                    {group.label}
                  </h3>
                  <span className="text-xs font-medium text-ink-faint">
                    {group.rows.length} series
                  </span>
                  <div className="h-px flex-1 bg-line" />
                </div>
                <div className="grid gap-3 lg:grid-cols-2">
                  {group.rows.map(({ series: s, chapters }) => (
                    <div
                      key={s.id}
                      className="group flex gap-4 rounded-[14px] border border-line bg-paper p-3.5 transition-all hover:border-accent/40 hover:shadow-md"
                    >
                      <a
                        href={`${seriesHref(s)}`}
                        onClick={link(`${seriesHref(s)}`)}
                        className="relative h-[104px] w-[76px] shrink-0 overflow-hidden rounded-lg ring-1 ring-black/5"
                      >
                        <Cover series={s} showTitle={false} rounded="rounded-lg" />
                      </a>
                      <div className="min-w-0 flex-1">
                        <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
                          <a
                            href={`${seriesHref(s)}`}
                            onClick={link(`${seriesHref(s)}`)}
                            className="line-clamp-1 text-sm font-bold tracking-tight hover:text-accent"
                          >
                            {s.title}
                            <span className="ml-1.5 font-semibold text-accent">
                              — Ch. {chapters[0].number}
                            </span>
                          </a>
                          <StatusBadge status={s.status} />
                        </div>
                        <div className="mt-1.5 flex flex-wrap items-center gap-x-3 gap-y-1">
                          <span className="inline-flex items-center gap-1 text-[11px] font-medium text-ink-faint">
                            <Clock width={11} height={11} />
                            {relativeDate(chapters[0].releaseDate)}
                          </span>
                          {s.genres.slice(0, 4).map((g) => (
                            <a
                              key={g}
                              href={genreHref(g)}
                              onClick={link(genreHref(g))}
                              className="rounded-full border border-line px-2 py-0.5 text-[10px] font-medium text-ink-soft transition-colors hover:border-accent hover:text-accent"
                            >
                              {g}
                            </a>
                          ))}
                        </div>
                        {/* latest chapters, newest first */}
                        <div className="mt-2 flex flex-wrap gap-1.5">
                          {chapters.map((chapter) => (
                            <a
                              key={chapter.id}
                              href={chapterHref(s, chapter.number)}
                              onClick={link(chapterHref(s, chapter.number))}
                              className="rounded-full border border-line bg-paper-2 px-2.5 py-1 text-[11px] font-semibold text-ink-soft transition-colors hover:border-accent hover:text-accent"
                            >
                              Ch. {chapter.number}
                            </a>
                          ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Keep exploring */}
        <section className="mt-16">
          <div className="eyebrow mb-4 text-accent">Keep Exploring</div>
          <div className="grid gap-3 sm:grid-cols-3">
            {keepExploring.map((item) => (
              <a
                key={item.href}
                href={item.href}
                onClick={link(item.href)}
                className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
              >
                <div>
                  <div className="font-extrabold tracking-tight group-hover:text-accent">
                    {item.title}
                  </div>
                  <div className="mt-0.5 text-xs text-ink-faint">{item.hint}</div>
                </div>
                <ArrowRight
                  width={18}
                  height={18}
                  className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent"
                />
              </a>
            ))}
          </div>
        </section>
      </div>
    </main>
  )
}
